window.JALUR_SET_JOURNAL = items => { state.journal = Array.isArray(items) ? items : []; saveState(); render(); };
window.JALUR_GET_WORKSPACE = () => ({profile:state.profile,notes:state.notes,compared:state.compared,mainChoice:state.mainChoice,alternatives:state.alternatives,checked:state.checked,costPlans:state.costPlans,pathwayGroups:state.pathwayGroups,settings:state.settings});
window.JALUR_SET_WORKSPACE = workspace => { if(!workspace||typeof workspace!=="object")return; for(const key of ["profile","notes","compared","mainChoice","alternatives","checked","costPlans","pathwayGroups","settings"])if(Object.prototype.hasOwnProperty.call(workspace,key))state[key]=workspace[key]; saveState(); render(); };
window.JALUR_SET_ACCOUNT_NAME = name => { const clean=String(name||"").trim(); if(!clean)return; if(!String(state.profile.nickname||"").trim())state.profile.nickname=clean; saveState(); render(); };
window.JALUR_GET_ACTIVE_PAGE = () => currentPage;
window.JALUR_SET_ACTIVE_PAGE = page => { if(!JALUR_PAGES.includes(page))return;currentPage=page;state.currentPage=page;jalurWriteRoute(page);saveState();const label=PAGE_LABELS[page]||page;const crumb=$("#pageCrumb");if(crumb)crumb.textContent=label;$$("[data-page],.bottom-item[data-page],.nav-item[data-page]").forEach(b=>b.classList.toggle("active",b.dataset.page===page));const primaryBottom=["Dashboard","Study Program Explorer","Decision Comparison","Plan B Builder"];$("#moreNav")?.classList.toggle("active",!primaryBottom.includes(page));const activeNav=$(".side-nav .nav-item.active");if(activeNav&&activeNav.offsetParent!==null)activeNav.scrollIntoView({block:"nearest"}); };


// The optional journal program selector hydrates only when a user opens it.
document.addEventListener("focusin",e=>{
  if(e.target?.id!=="journalProgram"||directoryDataReady||directoryDataFailed)return;
  const select=e.target,selected=select.value;
  select.disabled=true;
  loadDirectoryData().then(()=>{
    if(select.isConnected){select.innerHTML=programOptions(selected);select.disabled=false;}
  }).catch(error=>{
    if(select.isConnected)select.disabled=false;
    toast(error.message||"Direktori program studi belum dapat dimuat.","error");
  });
});

// Restore the last in-app page after a refresh in this tab. A new visit still
// starts at the welcome screen; only an active session is resumed.
let jalurResumeApp=false;
try{
  // Refresh resumes only in this tab; a fresh visit opens the welcome/login screen.
  jalurResumeApp=sessionStorage.getItem("jalur-app-open")==="1";
  localStorage.removeItem("jalur-app-open");
}catch{jalurResumeApp=false;}
if(jalurResumeApp){
  document.documentElement.classList.remove("jalur-welcome-mode");
  $("#welcome")?.classList.add("hidden");
  $("#app")?.classList.remove("hidden");
  render();
}else{
  document.documentElement.classList.add("jalur-welcome-mode");
}

/* Accessible pointer/touch drag interaction for welcome-screen satellites. */
(()=>{
 const visual=document.querySelector(".welcome-visual");
 if(!visual||visual.dataset.dragReady==="1")return;
 visual.dataset.dragReady="1";
 let active=null,offsetX=0,offsetY=0;
 const clamp=(v,min,max)=>Math.max(min,Math.min(max,v));
 visual.querySelectorAll("[data-draggable='true']").forEach(el=>{
  el.addEventListener("pointerdown",event=>{
   if(!document.documentElement.classList.contains("jalur-welcome-mode"))return;
   const rect=visual.getBoundingClientRect(),item=el.getBoundingClientRect();
   const left=item.left-rect.left,top=item.top-rect.top;
   el.style.left=left+"px";el.style.top=top+"px";el.style.right="auto";el.style.bottom="auto";el.style.position="absolute";
   active=el;offsetX=event.clientX-rect.left-left;offsetY=event.clientY-rect.top-top;
   el.classList.add("is-dragging");try{el.setPointerCapture(event.pointerId)}catch{}event.preventDefault();
  });
  el.addEventListener("pointermove",event=>{
   if(active!==el)return;
   const rect=visual.getBoundingClientRect();
   el.style.left=clamp(event.clientX-rect.left-offsetX,0,rect.width-el.offsetWidth)+"px";
   el.style.top=clamp(event.clientY-rect.top-offsetY,0,rect.height-el.offsetHeight)+"px";
  });
  const finish=()=>{if(active===el){active=null;el.classList.remove("is-dragging")}};
  el.addEventListener("pointerup",finish);el.addEventListener("pointercancel",finish);el.addEventListener("lostpointercapture",finish);
  el.addEventListener("keydown",event=>{
   const step=event.shiftKey?18:8;let dx=0,dy=0;
   if(event.key==="ArrowLeft")dx=-step;else if(event.key==="ArrowRight")dx=step;else if(event.key==="ArrowUp")dy=-step;else if(event.key==="ArrowDown")dy=step;else return;
   event.preventDefault();const rect=visual.getBoundingClientRect(),item=el.getBoundingClientRect();
   const left=el.style.left?parseFloat(el.style.left):item.left-rect.left,top=el.style.top?parseFloat(el.style.top):item.top-rect.top;
   el.style.position="absolute";el.style.right="auto";el.style.bottom="auto";
   el.style.left=clamp(left+dx,0,rect.width-el.offsetWidth)+"px";el.style.top=clamp(top+dy,0,rect.height-el.offsetHeight)+"px";
  });
 });
 const showGradeDetail=point=>{const wrap=point.closest(".grade-chart-wrap");if(!wrap)return;const tip=wrap.querySelector(".grade-chart-tooltip");if(!tip)return;tip.textContent=point.dataset.gradeTooltip||point.getAttribute("aria-label")||"";tip.hidden=false;const wr=wrap.getBoundingClientRect(),pr=point.getBoundingClientRect();tip.style.left=Math.max(8,Math.min(wr.width-tip.offsetWidth-8,pr.left-wr.left+pr.width/2-tip.offsetWidth/2))+"px";tip.style.top=Math.max(4,pr.top-wr.top-tip.offsetHeight-12)+"px";};
 document.addEventListener("pointerover",e=>{const p=e.target.closest?.(".grade-chart-point");if(p&&e.pointerType!=="touch")showGradeDetail(p)});
  document.addEventListener("pointerout",e=>{const p=e.target.closest?.(".grade-chart-point");if(p&&document.activeElement!==p){const tip=p.closest(".grade-chart-wrap")?.querySelector(".grade-chart-tooltip");if(tip)tip.hidden=true}});
 document.addEventListener("focusin",e=>{const p=e.target.closest?.(".grade-chart-point");if(p)showGradeDetail(p)});
 document.addEventListener("click",e=>{const p=e.target.closest?.(".grade-chart-point");if(p)showGradeDetail(p);else document.querySelectorAll(".grade-chart-tooltip:not([hidden])").forEach(t=>t.hidden=true)});
 document.addEventListener("keydown",e=>{if(e.key==="Escape")document.querySelectorAll(".grade-chart-tooltip:not([hidden])").forEach(t=>t.hidden=true)});
 // Responsive ambient interaction: cursor movement and touch-drag gently shift
 // the light field and its blue/lavender/pearl color balance on the welcome/login screen.
 const ambient=document.querySelector(".ambient");
 const welcomeMotion=()=>document.documentElement.classList.contains("jalur-welcome-mode");
 if(ambient&&!window.matchMedia("(prefers-reduced-motion: reduce)").matches){
  let touchActive=false;
  const updateAmbient=event=>{
   if(!welcomeMotion())return;
   if(event.pointerType==="touch"&&!touchActive)return;
   const x=Math.max(0,Math.min(1,event.clientX/Math.max(1,window.innerWidth)));
   const y=Math.max(0,Math.min(1,event.clientY/Math.max(1,window.innerHeight)));
   ambient.style.setProperty("--mouse-x",`${(x*100).toFixed(1)}%`);
   ambient.style.setProperty("--mouse-y",`${(y*100).toFixed(1)}%`);
   ambient.style.setProperty("--ambient-hue",`${Math.round((x-.5)*30)}deg`);
   ambient.style.setProperty("--ambient-shift-x",`${((x-.5)*22).toFixed(1)}px`);
   ambient.style.setProperty("--ambient-shift-y",`${((y-.5)*18).toFixed(1)}px`);
   ambient.classList.add("pointer-active");
  };
  ambient.addEventListener("pointerdown",event=>{
   if(event.pointerType==="touch"&&welcomeMotion()){touchActive=true;updateAmbient(event);}
  },{passive:true});
  window.addEventListener("pointermove",updateAmbient,{passive:true});
  const releaseAmbient=event=>{
   if(event.pointerType==="touch"){touchActive=false;ambient.classList.remove("pointer-active");}
  };
  window.addEventListener("pointerup",releaseAmbient,{passive:true});
  window.addEventListener("pointercancel",releaseAmbient,{passive:true});
  document.addEventListener("pointerleave",()=>ambient.classList.remove("pointer-active"));
 }
})();
